"""Deterministic test datasets.

Text formats (KML) are committed in this directory so they can be read and
opened in any GIS tool. Binary formats (zipped Shapefiles) are generated by
GDAL at test time from the definitions below, which keeps them reviewable in
code and avoids committing opaque binaries.
"""

from __future__ import annotations

from pathlib import Path

import geopandas as gpd
from shapely.geometry import Polygon

from tests.factories import write_shapefile_zip

FIXTURES_DIR = Path(__file__).resolve().parent

POLYGON_4326 = FIXTURES_DIR / "polygon_4326.kml"
LINE_4326 = FIXTURES_DIR / "line_4326.kml"
POINT_4326 = FIXTURES_DIR / "point_4326.kml"
MIXED_FEATURES = FIXTURES_DIR / "mixed_features.kml"

# Exact metric geometry in WGS 84 / UTM zone 43N (Pune): areas are known exactly.
PROJECTED_POLYGON_CRS = "EPSG:32643"
PROJECTED_POLYGON_AREAS = (10_000.0, 1_000.0)


def projected_polygon_zip(workdir: Path, *, with_prj: bool = True) -> Path:
    """``projected_polygon``: a 100 m x 100 m plot and a 50 m x 20 m plot."""
    frame = gpd.GeoDataFrame(
        {"plot_id": ["PN-1", "PN-2"], "ward": [3, 3]},
        geometry=[
            Polygon(
                [
                    (370_000, 2_047_000),
                    (370_100, 2_047_000),
                    (370_100, 2_047_100),
                    (370_000, 2_047_100),
                ]
            ),
            Polygon(
                [
                    (370_200, 2_047_000),
                    (370_250, 2_047_000),
                    (370_250, 2_047_020),
                    (370_200, 2_047_020),
                ]
            ),
        ],
        crs=PROJECTED_POLYGON_CRS,
    )
    return write_shapefile_zip(workdir, frame, stem="projected_polygon", with_prj=with_prj)
